const today = $now.toFormat('yyyy-MM-dd');
const rows = $input.all().map(i => i.json);
const activeStatuses = ['pending review', 'approved for publishing', 'published'];

const todayRows = rows.filter(r => {
  const d = (r.date || '').toString().slice(0, 10);
  return d === today && r.profile === 'Rob' && r.channel === 'LinkedIn' && activeStatuses.includes(r.status);
});

return [{
  json: {
    limitReached: todayRows.length >= 1,
    countToday: todayRows.length,
    today
  }
}];

const rotation = {
  1: 'AI applied to engineering team leadership (processes, decisions, culture — AI as an enabler, never the protagonist)',
  2: 'Developer Experience and engineering productivity (tools, friction, team velocity)',
  3: 'Engineering process improvement (Planning, Sprint, PR Reviews, onboarding)',
  4: 'Practical Engineering Management with measurable results (management decisions, 1:1s, feedback, team structure)',
  5: 'Technology applied to real life in a light and pleasant way to close the work week — how technology gives us more peace of mind, free time or well-being, real and human cases, less technical than the rest of the week, without fully losing the connection to the Engineering Management world'
};

const weekday = $now.weekday; // Luxon: 1=Monday ... 7=Sunday
const topic = rotation[weekday] || rotation[1];
const weekdayNames = { 1: 'Monday', 2: 'Tuesday', 3: 'Wednesday', 4: 'Thursday', 5: 'Friday' };

return [{ json: { topic, weekdayName: weekdayNames[weekday] || 'Monday' } }];

const isTrue = (v) => v === true || String(v).trim().toUpperCase() === 'TRUE';

const sources = $input.all()
  .map(i => i.json)
  .filter(row => isTrue(row.active) && row.url)
  .map(row => ({ name: row.source_name || row.url, url: row.url }));

const getTag = (block, tag) => {
  const re = new RegExp(`<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`, 'i');
  const m = block.match(re);
  if (!m) return '';
  return m[1].replace(/<!\[CDATA\[|\]\]>/g, '').replace(/<[^>]+>/g, '').trim();
};

const getAtomLink = (block) => {
  const tagMatch = block.match(/<link[^>]*>/i);
  if (!tagMatch) return '';
  const tag = tagMatch[0];
  const hrefIdx = tag.indexOf('href=');
  if (hrefIdx === -1) return '';
  const rest = tag.slice(hrefIdx + 5);
  const quoteChar = rest[0];
  const endIdx = rest.indexOf(quoteChar, 1);
  if (endIdx === -1) return '';
  return rest.slice(1, endIdx);
};

const allArticles = [];

for (const source of sources) {
  try {
    const response = await this.helpers.httpRequest({
      method: 'GET',
      url: source.url,
      timeout: 10000
    });

    const xml = typeof response === 'string' ? response : String(response);
    const itemBlocks = xml.match(/<item[\s\S]*?<\/item>/g) || xml.match(/<entry[\s\S]*?<\/entry>/g) || [];

    for (const block of itemBlocks.slice(0, 5)) {
      const title = getTag(block, 'title');
      let link = getTag(block, 'link');
      if (!link) link = getAtomLink(block);
      const pubDate = getTag(block, 'pubDate') || getTag(block, 'published') || getTag(block, 'updated');
      const summary = (getTag(block, 'description') || getTag(block, 'summary')).slice(0, 500);

      if (title && link) {
        allArticles.push({ source: source.name, title, link, pubDate, summary });
      }
    }
  } catch (error) {
    allArticles.push({ source: source.name, error: true, message: error.message });
  }
}

return allArticles.map(a => ({ json: a }));

const crypto = require('crypto');
const history = $('Sheets - Read Full History').all().map(i => i.json);
const knownHashes = new Set(history.map(r => r.content_hash).filter(Boolean));
const knownUrls = new Set(history.map(r => r.article_url).filter(Boolean));

const input = $input.all().map(i => i.json).filter(a => !a.error);

const deduped = [];
const seenInBatch = new Set();

for (const article of input) {
  const hash = crypto.createHash('sha256').update(article.link).digest('hex');
  if (knownHashes.has(hash) || knownUrls.has(article.link) || seenInBatch.has(hash)) continue;
  seenInBatch.add(hash);
  deduped.push({ ...article, url_hash: hash });
}

return [{ json: { articles: deduped, count: deduped.length } }];

const raw = $json.choices?.[0]?.message?.content || '{}';
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  throw new Error('DeepSeek did not return valid JSON in the filtering step: ' + raw.slice(0, 300));
}

const selected = (parsed.selected || []).slice(0, 3);

if (selected.length === 0) {
  return [{ json: { noSelection: true } }];
}

return selected.map(s => ({ json: { ...s, noSelection: false } }));

const crypto = require('crypto');
const response = $json;
let draftEs = '';
let draftEn = '';
try {
  const parsed = JSON.parse(response.choices?.[0]?.message?.content || '{}');
  draftEs = parsed.draft_es || '';
  draftEn = parsed.draft_en || '';
} catch (e) {
  draftEs = response.choices?.[0]?.message?.content || '';
  draftEn = '';
}

draftEs = (draftEs || '').trim().slice(0, 1100);
draftEn = (draftEn || '').trim().slice(0, 1100);

const draftText = draftEs + '\n\n\u2014\n\n\ud83c\uddfa\ud83c\uddf8 English version\n\n' + draftEn;

const article = $('Code - Parse DeepSeek Selection').item.json;
const dayTopic = $('Code - Topic of the Day').first().json.topic;
const contentHash = crypto.createHash('sha256').update(draftText).digest('hex');

return [{
  json: {
    date: $now.toFormat('yyyy-MM-dd'),
    profile: 'Rob',
    channel: 'LinkedIn',
    sources_consulted: article.source || '',
    article_title: article.title || '',
    article_url: article.link || '',
    draft_content: draftText,
    content_hash: contentHash,
    status: 'pending review',
    published_at: '',
    telegram_message_id: '',
    day_topic: dayTopic
  }
}];

