const row = $json;
const callbackId = row.content_hash.slice(0, 16);

const text = '📝 New draft for review — Rob LinkedIn\n\n' +
  'Topic of the day: ' + row.day_topic + '\n\n' +
  'Source: ' + row.sources_consulted + '\n' +
  'Article: ' + row.article_title + '\n' + row.article_url + '\n\n' +
  'Draft:\n' + row.draft_content;

return [{ json: { ...row, telegram_text: text, callback_id: callbackId } }];

const data = $json;
const errorMessage = data.execution?.error?.message || 'Error desconocido';
const lastNode = data.execution?.lastNodeExecuted || 'N/A';
const workflowName = data.workflow?.name || 'Rob - LinkedIn Content Curation v1';

return [{
  json: {
    text: '🚨 Error en ' + workflowName + '\n\nNodo: ' + lastNode + '\nMensaje: ' + errorMessage
  }
}];

const cb = $json.callback_query;
if (!cb) {
  return [];
}

const parts = (cb.data || '').split('|');
const decision = parts[0];
const callbackId = parts[1];

return [{
  json: {
    decision,
    callback_id: callbackId,
    from: cb.from?.username || cb.from?.id,
    callback_query_id: cb.id,
    chat_id: cb.message?.chat?.id,
    message_id: cb.message?.message_id
  }
}];

const target = $('Code - Parse Callback').item.json;
const rows = $input.all().map(i => i.json);
const match = rows.find(r => (r.content_hash || '').startsWith(target.callback_id));

if (!match) {
  return [{ json: { ...target, found: false } }];
}

return [{ json: { ...target, found: true, content_hash: match.content_hash } }];
